function renderLesson(id){const productModule=data.modules.find(m=>m.id===id&&m.productSlug);if(productModule){location.replace('#produto/'+productModule.productSlug+'/training');return;}if(id==='midias-marketing'){renderMarketing();return;}if(id==='empresa'){renderCompany();return;}const m=data.modules.find(m=>m.id===id);if(!m){$('#aula').innerHTML='<h1>Módulo não encontrado</h1><a href="#trilha">Voltar à trilha</a>';return;}const i=data.modules.indexOf(m);$('#aula').innerHTML=`<article class="article"><a class="mini-link" href="#trilha">← Todos os módulos</a><div class="lesson-meta">MÓDULO ${String(i+1).padStart(2,'0')} · ${esc(m.time)}</div><h1>${esc(m.title)}</h1><p class="muted">${esc(m.lead)}</p>${m.id==='crm'?'<a class="btn primary" href="#leads">Abrir as 8 aulas práticas do Leads2b →</a>':''}${m.id==='produtos'?'<a class="btn" href="#produtos">Abrir fichas de produtos →</a>':''}${m.sections.map(([t,items])=>`<div class="panel"><h2>${esc(t)}</h2><ul class="list-clean">${items.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul></div>`).join('')}<div class="practice"><span class="eyebrow">Agora é sua vez</span><h3>Pratique com a liderança</h3><p>${esc(m.practice)}</p></div><div class="lesson-end"><label class="complete"><input type="checkbox" data-module="${m.id}" ${done.includes(m.id)?'checked':''}>Já estudei este módulo</label><a class="btn primary" href="${data.modules[i+1]?'#aula/'+data.modules[i+1].id:'#trilha'}">${data.modules[i+1]?'Próximo módulo →':'Voltar à trilha'}</a></div></article>`}
function queryTopic(){const q=norm($('#product-search').value).trim();return data.topics.find(t=>t.aliases.some(a=>norm(a)===q)||norm(t.label)===q)}
function photoMarkup(p,zoom=false){if(!p.image)return '<div class="product-monogram" aria-hidden="true">PA</div>';return zoom?`<button class="image-open" data-zoom><img src="${p.image}" alt="${esc(p.name)} — embalagem"><span>Ampliar foto ↗</span></button>`:`<img src="${p.image}" alt="Embalagem de ${esc(p.name)}" loading="lazy">`}
function renderProducts(reset=true){if(reset===true)productPage=1;const q=norm($('#product-search').value).trim(),cat=$('#category').value,selected=$('#product-topic').value,t=data.topics.find(x=>x.id===selected)||queryTopic(),sort=$('#product-sort').value;let list=data.products.filter(p=>{if(cat&&p.cat!==cat)return false;if(selected&&!p.topics[selected])return false;if(!q)return true;const qt=queryTopic();if(qt)return !!p.topics[qt.id];const hay=norm([p.name,p.pack,p.cat,p.tagline,p.ingredients,...Object.keys(p.topics).flatMap(k=>data.topics.find(t=>t.id===k)?.aliases||[])].join(' '));const words=hay.split(/[^a-z0-9+]+/);return q.split(/[^a-z0-9+]+/).filter(Boolean).every(w=>words.some(v=>v.startsWith(w)))});if(sort==='az')list.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));if(sort==='za')list.sort((a,b)=>b.name.localeCompare(a.name,'pt-BR'));const perPage=24,pages=Math.max(1,Math.ceil(list.length/perPage));productPage=Math.min(productPage,pages);const from=(productPage-1)*perPage,to=Math.min(from+perPage,list.length),shown=list.slice(from,to);$('#results-count').textContent=list.length+' de '+data.products.length+' itens'+(list.length?' · exibindo '+(from+1)+'–'+to:'');$$('[data-topic]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.topic===t?.id)));$('#product-list').innerHTML=shown.length?shown.map(p=>`<a class="product-card" href="#produto/${p.slug}" style="--product-color:${p.color}"><div class="product-card-media">${photoMarkup(p)}<span>${esc(p.cat)}</span></div><div class="product-card-body"><h2>${esc(p.name)}</h2><p>${esc(p.tagline)}</p>${t&&p.topics[t.id]?'<div class="reason">'+esc(p.topics[t.id])+'</div>':''}<div class="card-meta"><span>${esc(p.pack)}</span><span aria-hidden="true">↗</span></div></div></a>`).join(''):'<div class="panel empty"><h2>Nenhum produto encontrado</h2><p>Experimente um nome, ingrediente ou assunto, como magnésio, digestão ou sono.</p><button class="btn" data-clear>Limpar a busca</button></div>';$('#product-pagination').innerHTML=list.length>perPage?`<button class="btn" data-page="${productPage-1}" ${productPage===1?'disabled':''}>← Anterior</button><label>Página <select id="catalog-page" aria-label="Ir para a página">${Array.from({length:pages},(_,i)=>`<option value="${i+1}" ${productPage===i+1?'selected':''}>${i+1} de ${pages}</option>`).join('')}</select></label><button class="btn" data-page="${productPage+1}" ${productPage===pages?'disabled':''}>Próxima →</button>`:''}
