function trainingInvitation(p){return `<div class="tech-invitation"><div><span class="eyebrow">Aprofunde seu conhecimento</span><h2>Treinamento técnico de ${esc(p.name)}</h2><p>Composição, qualidade e atendimento, em ${esc(p.technicalTraining.time)} de leitura.</p></div><button class="btn primary" data-goto-tab="training">Começar o treinamento →</button></div>`}
