function technicalBlocks(blocks){return (blocks||[]).map(([heading,paragraphs])=>`<div class="tech-reading-block"><h4>${esc(heading)}</h4>${paragraphs.map(text=>`<p>${esc(text)}</p>`).join('')}</div>`).join('')}
