const personalKey='pa-televendas-personal-v1';
const deskToday=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const deskDate=s=>new Date(Number(s.slice(0,4)),Number(s.slice(5,7))-1,Number(s.slice(8,10)),12);
const deskMonthEnd=k=>{const [y,m]=k.split('-').map(Number);return k+'-'+new Date(y,m,0,12).getDate()};
const validMonth=k=>typeof k==='string'&&/^20\d{2}-(0[1-9]|1[0-2])$/.test(k);
const validDate=s=>typeof s==='string'&&/^20\d{2}-(0[1-9]|1[0-2])-\d{2}$/.test(s)&&s.slice(-2)>='01'&&s<=deskMonthEnd(s.slice(0,7));
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n/100);
const moneyInput=n=>new Intl.NumberFormat('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n/100);
const shortDate=s=>s?deskDate(s).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'}):'Sem data';
const longDate=s=>deskDate(s).toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'});
const monthTitle=k=>deskDate(k+'-01').toLocaleDateString('pt-BR',{month:'long',year:'numeric'});
const newPersonal=()=>({schema:1,profile:{name:''},months:{}});
const newMonth=()=>({goal:7000000,weekdays:[1,2,3,4,5],daysOff:[],sales:[],tasks:[],events:[],notes:''});
const deskId=()=>globalThis.crypto?.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
function parseMoney(value){
 let s=String(value).trim().replace(/^R\$\s*/,'').replace(/\s/g,'');if(!s)return NaN;
 if(s.includes(',')){if(!/^(?:\d+|\d{1,3}(?:\.\d{3})+),\d{1,2}$/.test(s))return NaN;s=s.replace(/\./g,'').replace(',','.');}
 else if(/^\d{1,3}(?:\.\d{3})+$/.test(s))s=s.replace(/\./g,'');
 else if(!/^\d+(?:\.\d{1,2})?$/.test(s))return NaN;
 const n=Math.round(Number(s)*100);return Number.isSafeInteger(n)&&n<=100000000000?n:NaN;
}
function validatePersonal(input){
 if(!input||input.schema!==1||!input.profile||typeof input.profile.name!=='string'||!input.months||typeof input.months!=='object'||Array.isArray(input.months))throw Error('Formato de backup inválido.');
 const out=newPersonal();out.profile.name=input.profile.name.slice(0,80);
 if(Object.keys(input.months).length>1200)throw Error('O arquivo contém meses demais.');
 for(const [k,m]of Object.entries(input.months)){
  if(!validMonth(k)||!m||!Number.isSafeInteger(m.goal)||m.goal<=0||m.goal>100000000000)throw Error('Meta ou mês inválido no arquivo.');
  if(!Array.isArray(m.weekdays)||!m.weekdays.length||!m.weekdays.every(x=>Number.isInteger(x)&&x>=0&&x<=6))throw Error('Dias de trabalho inválidos.');
  if(!Array.isArray(m.daysOff)||!m.daysOff.every(x=>validDate(x)&&x.startsWith(k)))throw Error('Folgas inválidas.');
  if(typeof m.notes!=='string'||m.notes.length>50000)throw Error('Anotações inválidas.');
  const n=newMonth();n.goal=m.goal;n.weekdays=[...new Set(m.weekdays)];n.daysOff=[...new Set(m.daysOff)];n.notes=m.notes;
  for(const type of ['sales','tasks','events']){
   if(!Array.isArray(m[type])||m[type].length>10000)throw Error('Lista de registros inválida.');
   const ids=new Set();n[type]=m[type].map(x=>{
    if(!x||typeof x.id!=='string'||!x.id||x.id.length>100||ids.has(x.id))throw Error('Identificação de registro inválida.');ids.add(x.id);
    const str=(v,max=200)=>{if(typeof v!=='string'||v.length>max)throw Error('Texto inválido no arquivo.');return v};
    const date=v=>{if(!validDate(v)||!v.startsWith(k))throw Error('Data fora do mês do registro.');return v};
    if(type==='sales'){if(!Number.isSafeInteger(x.amount)||x.amount<=0||x.amount>100000000000)throw Error('Valor de venda inválido.');return{id:x.id,date:date(x.date),amount:x.amount,description:str(x.description)};}
    if(type==='tasks'){if(typeof x.done!=='boolean'||!['normal','alta'].includes(x.priority))throw Error('Tarefa inválida.');return{id:x.id,title:str(x.title),due:x.due?date(x.due):'',priority:x.priority,done:x.done};}
    if(x.time&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(x.time))throw Error('Horário inválido.');return{id:x.id,title:str(x.title),date:date(x.date),time:str(x.time,5),notes:str(x.notes,1000)};
   });
  }
  out.months[k]=n;
 }
 return out;
}
let personal,personalError='',personalLocked=false,personalSaved=true;
try{const raw=localStorage.getItem(personalKey);if(raw){try{personal=validatePersonal(JSON.parse(raw));}catch{personal=newPersonal();personalLocked=true;personalError='Não foi possível abrir seus dados salvos. Importe um backup para recuperá-los. Os registros anteriores não serão substituídos automaticamente.';}}else personal=newPersonal();}
catch{personal=newPersonal();personalSaved=false;personalError='O salvamento automático está indisponível neste navegador. Exporte seus dados antes de fechar.';}
let deskMonth=deskToday().slice(0,7),deskDay=deskToday(),deskTab='painel',taskFilter='pendentes',deskDialogType='',deskEditId='',deskTrigger=null;
function deskData(){if(!personal.months[deskMonth])personal.months[deskMonth]=newMonth();return personal.months[deskMonth];}
function savePersonal(){return persistUserData();}
function updatePersonalStatus(){const s=$('#desk-save-status');if(s){s.textContent=personalError||(personalSaved?'Salvo neste navegador':'Alterações nesta sessão');s.classList.toggle('save-error',!!personalError);}}
function deskStats(m=deskData(),key=deskMonth,today=deskToday()){
 const days=Array.from({length:Number(deskMonthEnd(key).slice(-2))},(_,i)=>key+'-'+String(i+1).padStart(2,'0'));
 const working=days.filter(d=>m.weekdays.includes(deskDate(d).getDay())&&!m.daysOff.includes(d));
 const total=m.sales.filter(s=>s.date<=today).reduce((a,s)=>a+s.amount,0);
 const elapsedDays=working.filter(d=>d<=today).length,remainingDays=working.filter(d=>d>=today).length;
 const remaining=Math.max(0,m.goal-total),over=Math.max(0,total-m.goal),percent=total/m.goal*100;
 const future=key>today.slice(0,7),past=key<today.slice(0,7);
 const projection=past?total:!future&&elapsedDays&&m.sales.some(s=>s.date<=today)?Math.round(total/elapsedDays*working.length):null;
 return{total,remaining,over,percent,working,elapsedDays,remainingDays,projection,future,past,daily:remainingDays?Math.ceil(remaining/remainingDays):null,days};
}
function switchDeskMonth(k){if(!validMonth(k))return;deskMonth=k;deskDay=k===deskToday().slice(0,7)?deskToday():k+'-01';renderDesk();}
function shiftDeskMonth(delta){const d=deskDate(deskMonth+'-01');d.setMonth(d.getMonth()+delta);switchDeskMonth(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'));}
function sortedTasks(m=deskData()){return[...m.tasks].sort((a,b)=>Number(a.done)-Number(b.done)||(a.due||'9999').localeCompare(b.due||'9999')||(a.priority==='alta'?-1:1)-(b.priority==='alta'?-1:1));}
