function renderDesk(){
 const m=deskData(),s=deskStats(m),tabs=[['painel','Visão do mês'],['vendas','Vendas'],['agenda','Calendário'],['tarefas','Tarefas']];
 $('#meumes').innerHTML=`<div class="desk-heading"><div><div class="eyebrow">Seu espaço de trabalho</div><h1>Meu mês${personal.profile.name?'<span> · '+esc(personal.profile.name)+'</span>':''}</h1><p>Organize a rotina e acompanhe cada passo até a sua meta.</p></div><button class="btn" data-desk-action="settings">${di('edit')} Editar meta e perfil</button></div><div class="desk-toolbar"><div class="desk-month-picker"><button class="desk-icon-button" data-desk-action="prev-month" aria-label="Mês anterior">←</button><label for="desk-month">Mês de referência<input id="desk-month" type="month" min="2000-01" max="2099-12" value="${deskMonth}"></label><button class="desk-icon-button" data-desk-action="next-month" aria-label="Próximo mês">→</button><button class="desk-text-button" data-desk-action="this-month">Este mês</button></div><button class="btn primary" data-desk-action="sale-new">${di('plus')} Registrar venda</button></div><div class="desk-tabs" role="tablist" aria-label="Meu mês">${tabs.map(([id,title])=>`<button id="desk-tab-${id}" data-desk-tab="${id}" role="tab" aria-selected="${deskTab===id}" aria-controls="desk-panel" tabindex="${deskTab===id?0:-1}">${title}${id==='tarefas'&&m.tasks.some(t=>!t.done)?'<span>'+m.tasks.filter(t=>!t.done).length+'</span>':''}</button>`).join('')}</div><div id="desk-panel" role="tabpanel" aria-labelledby="desk-tab-${deskTab}">${deskTab==='painel'?renderDeskOverview(m,s):deskTab==='vendas'?renderDeskSales(m,s):deskTab==='agenda'?renderDeskCalendar(m,s):renderDeskTasks(m)}</div><div class="desk-backup"><div><span id="desk-save-status" role="status"></span><p>Antes de abrir uma nova versão, exporte seus dados. O arquivo inclui todos os meses e seu progresso no treinamento.</p></div><div><button class="btn" data-desk-action="export">${di('download')} Exportar meus dados</button><button class="desk-text-button" data-desk-action="import">Importar dados</button><a class="desk-text-button" href="#dados">Meus dados →</a></div></div>`;
 updatePersonalStatus();
}
function renderDeskOverview(m,s){
 const pct=new Intl.NumberFormat('pt-BR',{maximumFractionDigits:1}).format(s.percent),hit=s.remaining===0;
 const nextEvents=[...m.events].filter(e=>e.date>=deskToday()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,3),pending=sortedTasks(m).filter(t=>!t.done).slice(0,3);
 return `<div class="desk-goal ${hit?'goal-achieved':''}"><div class="desk-goal-top"><div><span class="eyebrow">${hit?'Meta alcançada':'Meta de '+esc(monthTitle(deskMonth))}</span><h2>${money(m.goal)}</h2><p>${hit?'Você chegou à meta. Continue registrando suas vendas.':s.past?'Mês encerrado. Consulte ou ajuste seus registros.':s.future?'Prepare o mês e organize seus próximos contatos.':'Cada venda registrada atualiza o seu progresso.'}</p></div><div class="desk-percent"><strong>${pct}<small>%</small></strong><span>da meta atingida</span></div></div><div class="desk-goal-bar" role="progressbar" aria-label="Percentual da meta atingida" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,s.percent).toFixed(1)}" aria-valuetext="${pct}% da meta"><span style="width:${Math.min(100,s.percent)}%"></span></div><div class="desk-goal-foot"><div><span>Vendido no mês</span><strong>${money(s.total)}</strong></div><div><span>${hit?'Acima da meta':'Falta para chegar lá'}</span><strong>${money(hit?s.over:s.remaining)}</strong></div><button class="desk-text-button" data-desk-action="settings">Editar meta ↗</button></div></div><div class="desk-kpis"><div><span>Necessário por dia</span><strong>${s.daily===null?'—':money(s.daily)}</strong><small>${s.past?'O período deste mês já terminou.':s.remainingDays?s.remainingDays+' dia(s) de trabalho, incluindo hoje quando marcado.':'Sem dias de trabalho restantes neste mês.'}</small></div><div><span>Dias de trabalho restantes</span><strong>${s.remainingDays}<small> de ${s.working.length}</small></strong><small>Ajuste os dias da semana e marque folgas no calendário.</small></div><div class="desk-projection"><span>${s.past?'Resultado do mês':'Projeção de fechamento'}</span><strong>${s.projection===null?'—':money(s.projection)}</strong><small>${s.past?'Total vendido no mês encerrado.':s.future?'A projeção começa quando o mês iniciar.':s.projection===null?'Registre as vendas para acompanhar o ritmo do mês.':'Estimativa pelo ritmo das vendas, incluindo hoje.'}</small>${!s.past&&!s.future&&s.projection!==null?`<details class="desk-projection-math"><summary>Ver cálculo</summary><p><strong>${money(s.total)}</strong> vendidos até ${shortDate(deskToday())} ÷ <strong>${s.elapsedDays}</strong> dia(s) de trabalho decorridos × <strong>${s.working.length}</strong> dia(s) de trabalho no mês.</p><p>Hoje conta como um dia completo quando está marcado como dia de trabalho. Dias sem vendas entram na média; folgas ficam de fora.</p></details>`:''}</div></div>${renderDeskChart(m,s)}<div class="desk-widgets"><section class="desk-card"><div class="desk-card-head"><h2>Próximas tarefas</h2><button class="desk-text-button" data-desk-tab="tarefas">Ver todas →</button></div>${pending.length?`<div class="desk-task-list compact">${pending.map(renderTaskRow).join('')}</div>`:'<p class="desk-light-text">Nenhuma tarefa pendente neste mês. Organize seus retornos e prioridades.</p>'}<button class="btn" data-desk-action="task-new">${di('plus')} Nova tarefa</button></section><section class="desk-card"><div class="desk-card-head"><h2>Na agenda</h2><button class="desk-text-button" data-desk-tab="agenda">Calendário →</button></div>${nextEvents.length?nextEvents.map(e=>`<div class="desk-agenda-preview"><span>${shortDate(e.date)}</span><div><strong>${esc(e.title)}</strong><small>${e.time||'Sem horário definido'}</small></div></div>`).join(''):'<p class="desk-light-text">Reserve datas para ligações, reuniões e retornos de propostas.</p>'}<button class="btn" data-desk-action="event-new">${di('plus')} Novo compromisso</button></section></div>`;
}
function renderDeskChart(m,s){
 const compact=innerWidth<650,max=Math.max(m.goal,s.total,1),w=compact?420:920,h=165,l=compact?51:65,r=w-20,top=15,b=133,x=i=>l+(r-l)*i/(s.days.length-1),y=v=>b-(b-top)*v/max;
 let actual=0,target=0;const actualPts=[],targetPts=[];
 s.days.forEach((d,i)=>{if(s.working.includes(d))target+=m.goal/Math.max(1,s.working.length);targetPts.push(x(i).toFixed(1)+','+y(target).toFixed(1));if(d<=deskToday()){actual+=m.sales.filter(a=>a.date===d).reduce((v,a)=>v+a.amount,0);actualPts.push(x(i).toFixed(1)+','+y(actual).toFixed(1));}});
 const labels=[0,Math.floor((s.days.length-1)/2),s.days.length-1];
 return `<section class="desk-card desk-chart"><div class="desk-card-head"><h2>O caminho até a meta</h2><div class="desk-chart-legend"><span class="line-actual">Vendas acumuladas</span><span class="line-target">Ritmo da meta</span></div></div><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Vendas acumuladas de ${esc(money(s.total))} comparadas com a meta de ${esc(money(m.goal))}. O ritmo da meta distribui o objetivo pelos dias de trabalho.">${[0,.5,1].map(f=>`<line class="chart-grid" x1="${l}" x2="${r}" y1="${y(max*f)}" y2="${y(max*f)}"/><text x="${l-10}" y="${y(max*f)+4}" text-anchor="end">${new Intl.NumberFormat('pt-BR',{notation:'compact',maximumFractionDigits:1}).format(max*f/100)}</text>`).join('')}${s.working.length?`<polyline class="chart-target" points="${targetPts.join(' ')}"/>`:''}${actualPts.length>1?`<polyline class="chart-actual" points="${actualPts.join(' ')}"/>`:''}${actualPts.length?`<circle class="chart-point" cx="${actualPts.at(-1).split(',')[0]}" cy="${actualPts.at(-1).split(',')[1]}" r="4"/>`:''}${labels.map(i=>`<text x="${x(i)}" y="158" text-anchor="middle">${shortDate(s.days[i])}</text>`).join('')}</svg></section>`;
}
function renderDeskSales(m,s){
 const rows=[...m.sales].sort((a,b)=>b.date.localeCompare(a.date));
 return `<div class="desk-section-heading"><div><h2>Registro de vendas</h2><p>Registre cada venda ou o total de um dia. Use um único método para não contar o mesmo valor duas vezes.</p></div><div class="desk-section-total"><span>Total do mês</span><strong>${money(s.total)}</strong></div></div>${rows.length?`<div class="desk-card desk-sales-table"><div class="tablewrap"><table><thead><tr><th>Data</th><th>Descrição</th><th>Valor</th><th scope="col">Ações</th></tr></thead><tbody>${rows.map(v=>`<tr><td>${shortDate(v.date)}</td><td>${esc(v.description||'Venda registrada')}${v.date>deskToday()?'<small>Data futura · fora do total realizado</small>':''}</td><td>${money(v.amount)}</td><td><button class="desk-icon-button" data-desk-action="sale-edit" data-id="${esc(v.id)}" aria-label="Editar venda de ${esc(money(v.amount))} em ${shortDate(v.date)}">${di('edit')}</button><button class="desk-icon-button danger" data-desk-action="sale-delete" data-id="${esc(v.id)}" aria-label="Excluir venda de ${esc(money(v.amount))} em ${shortDate(v.date)}">${di('trash')}</button></td></tr>`).join('')}</tbody></table></div><p class="desk-table-caption">${rows.length} registro(s) em ${esc(monthTitle(deskMonth))}.</p></div>`:emptyDesk('Comece pelo primeiro registro','As vendas que você adicionar aqui vão atualizar a meta e o gráfico deste mês.','Registrar venda','sale-new')}`;
}
function renderTaskRow(t){const overdue=!t.done&&t.due&&t.due<deskToday();return `<div class="desk-task ${t.done?'task-done':''}"><label class="desk-task-check"><input type="checkbox" data-task-check="${esc(t.id)}" ${t.done?'checked':''} aria-label="${t.done?'Reabrir':'Concluir'} tarefa ${esc(t.title)}"><span>${esc(t.title)}</span></label><div class="desk-task-meta"><span class="${overdue?'overdue':''}">${t.due?(overdue?'Atrasada · ':'')+shortDate(t.due):'Sem prazo'}</span>${t.priority==='alta'?'<span class="desk-priority">Prioridade alta</span>':''}<button class="desk-icon-button" data-desk-action="task-edit" data-id="${esc(t.id)}" aria-label="Editar tarefa ${esc(t.title)}">${di('edit')}</button><button class="desk-icon-button danger" data-desk-action="task-delete" data-id="${esc(t.id)}" aria-label="Excluir tarefa ${esc(t.title)}">${di('trash')}</button></div></div>`;}
function renderDeskTasks(m){
 const list=sortedTasks(m).filter(t=>taskFilter==='todas'||(taskFilter==='concluidas'?t.done:!t.done)),completed=m.tasks.filter(t=>t.done).length;
 return `<div class="desk-section-heading"><div><h2>Minhas tarefas</h2><p>${completed} de ${m.tasks.length} concluída(s) neste mês.</p></div><button class="btn primary" data-desk-action="task-new">${di('plus')} Nova tarefa</button></div><div class="desk-task-filters" aria-label="Filtrar tarefas">${[['pendentes','Pendentes'],['todas','Todas'],['concluidas','Concluídas']].map(([k,l])=>`<button data-task-filter="${k}" aria-pressed="${taskFilter===k}">${l}</button>`).join('')}</div>${list.length?`<div class="desk-card desk-task-list">${list.map(renderTaskRow).join('')}</div>`:emptyDesk(taskFilter==='concluidas'?'Ainda não há tarefas concluídas':taskFilter==='pendentes'?'Tudo em dia por aqui':'Organize seus próximos passos','Adicione ligações, retornos de propostas e outras atividades. Marque e desmarque cada tarefa quando precisar.','Nova tarefa','task-new')}`;
}
function renderDeskCalendar(m,s){
 if(!deskDay.startsWith(deskMonth))deskDay=deskMonth+'-01';
 const blank=deskDate(deskMonth+'-01').getDay(),today=deskToday(),off=m.daysOff.includes(deskDay),scheduled=[...m.events].filter(e=>e.date===deskDay).sort((a,b)=>(a.time||'99').localeCompare(b.time||'99')),tasks=m.tasks.filter(t=>t.due===deskDay),sales=m.sales.filter(v=>v.date===deskDay);
 return `<div class="desk-section-heading"><div><h2>Calendário do mês</h2><p>Selecione um dia para consultar vendas, tarefas e compromissos ou marcar uma folga.</p></div><button class="btn primary" data-desk-action="event-new">${di('plus')} Novo compromisso</button></div><div class="desk-calendar-layout"><section class="desk-card desk-calendar"><div class="desk-calendar-title"><h3>${esc(monthTitle(deskMonth))}</h3><span>● Hoje</span></div><div class="desk-weekdays" aria-hidden="true">${['DOM','SEG','TER','QUA','QUI','SEX','SÁB'].map(d=>'<span>'+d+'</span>').join('')}</div><div class="desk-calendar-grid">${Array.from({length:blank},()=>'<span class="desk-calendar-blank"></span>').join('')}${s.days.map(d=>{const e=m.events.filter(x=>x.date===d).length,t=m.tasks.filter(x=>x.due===d&&!x.done).length,v=m.sales.filter(x=>x.date===d).reduce((a,x)=>a+x.amount,0),work=s.working.includes(d);return `<button data-desk-day="${d}" class="${d===today?'is-today ':''}${d===deskDay?'is-selected ':''}${work?'':'is-off'}" aria-pressed="${d===deskDay}" aria-label="${esc(longDate(d))}${m.daysOff.includes(d)?', folga':''}, ${e} compromisso(s), ${t} tarefa(s) pendente(s), vendas ${esc(money(v))}"><strong>${Number(d.slice(-2))}</strong>${m.daysOff.includes(d)?'<span class="calendar-off">Folga</span>':''}${v?`<span class="calendar-sales">${new Intl.NumberFormat('pt-BR',{notation:'compact',maximumFractionDigits:1}).format(v/100)}</span>`:''}<span class="calendar-dots">${e?'<i class="event-dot"></i>':''}${t?'<i class="task-dot"></i>':''}</span></button>`}).join('')}</div><div class="desk-calendar-legend"><span><i class="event-dot"></i>Compromisso</span><span><i class="task-dot"></i>Tarefa pendente</span><span class="off-legend">Dia sem trabalho</span></div></section><aside class="desk-card desk-day-detail"><div class="eyebrow">Dia selecionado</div><h3>${esc(longDate(deskDay))}</h3><div class="desk-day-actions"><button class="desk-text-button" data-desk-action="event-day">+ Compromisso</button><button class="desk-text-button" data-desk-action="day-off">${off?'Retirar folga':'Marcar folga'}</button></div>${off?'<p class="desk-off-note">Esta data está fora do cálculo de dias de trabalho.</p>':''}<div class="desk-day-sales"><span>Vendas no dia</span><strong>${money(sales.reduce((a,v)=>a+v.amount,0))}</strong></div><h4>Compromissos</h4>${scheduled.length?scheduled.map(e=>`<div class="desk-event"><div><span>${e.time||'Sem horário'}</span><strong>${esc(e.title)}</strong>${e.notes?'<p>'+esc(e.notes)+'</p>':''}</div><div><button class="desk-icon-button" data-desk-action="event-edit" data-id="${esc(e.id)}" aria-label="Editar compromisso ${esc(e.title)}">${di('edit')}</button><button class="desk-icon-button danger" data-desk-action="event-delete" data-id="${esc(e.id)}" aria-label="Excluir compromisso ${esc(e.title)}">${di('trash')}</button></div></div>`).join(''):'<p class="desk-light-text">Nenhum compromisso nesta data.</p>'}<h4>Tarefas com prazo neste dia</h4>${tasks.length?tasks.map(renderTaskRow).join(''):'<p class="desk-light-text">Nenhuma tarefa com este prazo.</p>'}<button class="btn" data-desk-action="task-day">+ Tarefa para este dia</button></aside></div>`;
}
function openDeskDialog(type,id='',day=''){
 const m=deskData();deskTrigger=document.activeElement;deskDialogType=type;deskEditId=id;
 if(type==='sale'&&deskMonth>deskToday().slice(0,7)){toast('Você pode planejar os próximos meses. Registre vendas em uma data até hoje.');return;}
 let title='',fields='';const first=deskMonth+'-01',last=deskMonthEnd(deskMonth),latest=last<deskToday()?last:deskToday();
 if(type==='settings'){
  title='Sua meta e sua rotina';fields=`<label>Seu nome<input name="name" type="text" maxlength="80" value="${esc(personal.profile.name)}" placeholder="Como você quer aparecer no painel"></label><label>Meta de ${esc(monthTitle(deskMonth))} · R$<input name="goal" type="text" inputmode="decimal" value="${moneyInput(m.goal)}" required maxlength="20"></label><fieldset><legend>Dias de trabalho neste mês</legend><div class="desk-workweek">${[[1,'Seg'],[2,'Ter'],[3,'Qua'],[4,'Qui'],[5,'Sex'],[6,'Sáb'],[0,'Dom']].map(([n,t])=>`<label><input type="checkbox" name="weekday" value="${n}" ${m.weekdays.includes(n)?'checked':''}><span>${t}</span></label>`).join('')}</div><p>Esses dias são usados no ritmo da meta e na projeção. Feriados e folgas podem ser marcados no calendário.</p></fieldset>`;
 }
 if(type==='sale'){
  const v=m.sales.find(x=>x.id===id);title=v?'Editar venda':'Registrar venda';fields=`<div class="desk-form-two"><label>Data<input name="date" type="date" value="${v?.date||latest}" min="${first}" max="${latest}" required></label><label>Valor vendido · R$<input name="amount" type="text" inputmode="decimal" value="${v?moneyInput(v.amount):''}" placeholder="Ex.: 1.250,00" maxlength="20" required autofocus></label></div><label>Descrição <span>(opcional)</span><input name="description" type="text" value="${esc(v?.description||'')}" maxlength="200" placeholder="Ex.: Pedido 123 ou total do dia"></label><p class="desk-form-hint">Lance cada venda ou o total do dia. Evite registrar o mesmo valor das duas formas.</p>`;
 }
 if(type==='task'){
  const t=m.tasks.find(x=>x.id===id);title=t?'Editar tarefa':'Nova tarefa';fields=`<label>O que precisa ser feito?<input name="title" type="text" value="${esc(t?.title||'')}" required maxlength="200" placeholder="Ex.: Retornar a proposta da Loja Central"></label><div class="desk-form-two"><label>Prazo <span>(opcional)</span><input name="due" type="date" value="${t?.due||day||''}" min="${first}" max="${last}"></label><label>Prioridade<select name="priority"><option value="normal" ${t?.priority!=='alta'?'selected':''}>Normal</option><option value="alta" ${t?.priority==='alta'?'selected':''}>Alta</option></select></label></div>`;
 }
 if(type==='event'){
  const a=m.events.find(x=>x.id===id);title=a?'Editar compromisso':'Novo compromisso';fields=`<label>Compromisso<input name="title" type="text" value="${esc(a?.title||'')}" required maxlength="200" placeholder="Ex.: Ligação com responsável de compras"></label><div class="desk-form-two"><label>Data<input name="date" type="date" value="${a?.date||day||deskDay}" min="${first}" max="${last}" required></label><label>Horário <span>(opcional)</span><input name="time" type="time" value="${a?.time||''}"></label></div><label>Observações <span>(opcional)</span><textarea name="notes" rows="3" maxlength="1000" placeholder="O que você precisa lembrar para esse contato?">${esc(a?.notes||'')}</textarea></label>`;
 }
 $('#desk-dialog-title').textContent=title;
 $('#desk-dialog-body').innerHTML=`<form id="desk-edit-form">${fields}<p id="desk-form-error" role="alert" hidden></p><div class="desk-form-actions"><button class="btn" type="button" data-desk-close>Cancelar</button><button class="btn primary" type="submit">${type==='settings'?'Salvar alterações':deskEditId?'Salvar alterações':'Adicionar'}</button></div></form>`;
 $('#desk-dialog').showModal();
}
function deskFormError(message){const e=$('#desk-form-error');e.textContent=message;e.hidden=false;}
function saveDeskForm(event){
 event.preventDefault();const f=new FormData(event.target),m=deskData(),type=deskDialogType,id=deskEditId||deskId(),get=k=>String(f.get(k)||'').trim();
 if(type==='settings'){
  const value=parseMoney(get('goal')),days=f.getAll('weekday').map(Number);
  if(!Number.isSafeInteger(value)||value<=0){deskFormError('Digite uma meta maior que zero. Exemplo: 70.000,00.');return;}
  if(!days.length){deskFormError('Selecione pelo menos um dia de trabalho.');return;}
  personal.profile.name=get('name');m.goal=value;m.weekdays=days;
 }else{
  let item,list;
  if(type==='sale'){
   const value=parseMoney(get('amount')),date=get('date');
   if(!Number.isSafeInteger(value)||value<=0){deskFormError('Digite um valor de venda maior que zero. Exemplo: 1.250,50.');return;}
   if(!validDate(date)||!date.startsWith(deskMonth)||date>deskToday()){deskFormError('Escolha uma data deste mês que seja até hoje.');return;}
   item={id,date,amount:value,description:get('description')};list=m.sales;
  }
  if(type==='task'){
   const due=get('due'),title=get('title');if(!title){deskFormError('Escreva o que precisa ser feito.');return;}
   if(due&&(!validDate(due)||!due.startsWith(deskMonth))){deskFormError('O prazo deve estar no mês selecionado.');return;}
   item={id,title,due,priority:get('priority'),done:m.tasks.find(t=>t.id===id)?.done||false};list=m.tasks;
  }
  if(type==='event'){
   const date=get('date'),title=get('title'),time=get('time');if(!title){deskFormError('Dê um nome ao compromisso.');return;}
   if(!validDate(date)||!date.startsWith(deskMonth)){deskFormError('Escolha uma data do mês selecionado.');return;}
   if(time&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(time)){deskFormError('Informe um horário válido.');return;}
   item={id,title,date,time,notes:get('notes')};list=m.events;
  }
  const index=list.findIndex(x=>x.id===id);if(index>=0)list[index]=item;else list.push(item);
 }
 const saved=savePersonal();$('#desk-dialog').close();renderDesk();toast(saved?'Alterações salvas.':'Alterações nesta sessão. Baixe um backup para guardar.');
}
function deleteDeskRecord(type,id){
 const m=deskData(),map={sale:'sales',task:'tasks',event:'events'},list=m[map[type]],item=list.find(x=>x.id===id);if(!item)return;
 const label=type==='sale'?'a venda de '+money(item.amount)+' em '+shortDate(item.date):'“'+item.title+'”';
 if(!confirm('Excluir '+label+'?'))return;m[map[type]]=list.filter(x=>x.id!==id);savePersonal();renderDesk();toast('Registro excluído.');
}
$('#meumes').addEventListener('click',e=>{
 const tab=e.target.closest('[data-desk-tab]');if(tab){deskTab=tab.dataset.deskTab;renderDesk();$('#desk-tab-'+deskTab).focus();return;}
 const day=e.target.closest('[data-desk-day]');if(day){deskDay=day.dataset.deskDay;renderDesk();$('[data-desk-day="'+deskDay+'"]').focus({preventScroll:true});return;}
 const filter=e.target.closest('[data-task-filter]');if(filter){taskFilter=filter.dataset.taskFilter;renderDesk();$('[data-task-filter="'+taskFilter+'"]').focus();return;}
 const b=e.target.closest('[data-desk-action]');if(!b)return;const a=b.dataset.deskAction,id=b.dataset.id||'';
 if(a==='prev-month')shiftDeskMonth(-1);if(a==='next-month')shiftDeskMonth(1);if(a==='this-month')switchDeskMonth(deskToday().slice(0,7));
 if(a==='settings')openDeskDialog('settings');
 for(const type of ['sale','task','event']){if(a===type+'-new')openDeskDialog(type);if(a===type+'-edit')openDeskDialog(type,id);if(a===type+'-delete')deleteDeskRecord(type,id);}
 if(a==='event-day')openDeskDialog('event','',deskDay);if(a==='task-day')openDeskDialog('task','',deskDay);
 if(a==='day-off'){const m=deskData();m.daysOff=m.daysOff.includes(deskDay)?m.daysOff.filter(d=>d!==deskDay):[...m.daysOff,deskDay];savePersonal();renderDesk();}
 if(a==='export')downloadPersonal();if(a==='import')$('#desk-import-file').click();
});
$('#meumes').addEventListener('change',e=>{
 if(e.target.id==='desk-month'){switchDeskMonth(e.target.value);return;}
 if(e.target.hasAttribute('data-task-check')){const id=e.target.dataset.taskCheck,t=deskData().tasks.find(t=>t.id===id);if(t){t.done=e.target.checked;savePersonal();renderDesk();const next=$('[data-task-check="'+id+'"]');if(next)next.focus({preventScroll:true});else $('#desk-tab-'+deskTab).focus({preventScroll:true});}}
});
$('#meumes').addEventListener('keydown',e=>{if(e.target.getAttribute('role')!=='tab'||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=['painel','vendas','agenda','tarefas'],i=tabs.indexOf(deskTab);deskTab=tabs[e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length];renderDesk();$('#desk-tab-'+deskTab).focus();});
$('#desk-dialog-body').addEventListener('submit',saveDeskForm);
$('#desk-dialog').addEventListener('click',e=>{if(e.target.closest('[data-desk-close]'))$('#desk-dialog').close();});
$('#desk-dialog').addEventListener('close',()=>{if(deskTrigger?.isConnected)deskTrigger.focus({preventScroll:true});else $('#desk-tab-'+deskTab)?.focus({preventScroll:true});});
$('#desk-import-file').addEventListener('change',e=>importPersonal(e.target.files[0]));
const guideTheme='classic';
function applyGuideTheme(){document.documentElement.dataset.theme=guideTheme;}
applyGuideTheme();

let deskResizeTimer;window.addEventListener('resize',()=>{clearTimeout(deskResizeTimer);deskResizeTimer=setTimeout(()=>{const chart=$('#meumes.active .desk-chart');if(chart)chart.outerHTML=renderDeskChart(deskData(),deskStats());},100);});

const backupMetaKey='pa-televendas-backup-meta-v1',guideVersion='14.2',backupFormat='pa-televendas-backup';
let backupMeta={savedAt:'',exportedAt:'',importedAt:''},pendingUserBackup=null,backupTrigger=null;
try{const m=JSON.parse(localStorage.getItem(backupMetaKey)||'{}');for(const k of Object.keys(backupMeta))if(typeof m[k]==='string'&&Number.isFinite(Date.parse(m[k])))backupMeta[k]=m[k];}catch{}
const backupStamp=s=>s&&Number.isFinite(Date.parse(s))?new Date(s).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}):'';
function userDataCounts(p=personal,training={modules:done,leads2b:crmDone}){
 const months=Object.values(p.months);return{months:months.length,sales:months.reduce((a,m)=>a+m.sales.length,0),tasks:months.reduce((a,m)=>a+m.tasks.length,0),events:months.reduce((a,m)=>a+m.events.length,0),lessons:training.modules.length+training.leads2b.length};
}
function storageTransaction(entries){
 const before=entries.map(([k])=>[k,localStorage.getItem(k)]);let written=0;
 try{for(const [k,v]of entries){localStorage.setItem(k,v);written++;}}
 catch(error){let restored=true;for(let i=written-1;i>=0;i--){try{const[k,v]=before[i];if(v===null)localStorage.removeItem(k);else localStorage.setItem(k,v);}catch{restored=false;}}
  throw Error(restored?'O navegador não conseguiu salvar. Os dados anteriores foram mantidos.':'O navegador interrompeu o salvamento. Mantenha esta página aberta e exporte seus dados.');}
}
function userStorageEntries(p,training,theme,meta){return[[personalKey,JSON.stringify(p)],[stateKey,JSON.stringify(training.modules)],[crmKey,JSON.stringify(training.leads2b)],['pa-guide-theme',theme],[backupMetaKey,JSON.stringify(meta)]];}
function persistUserData(){
 if(personalLocked){personalSaved=false;updatePersonalStatus();refreshUserDataStatus();toast('Os dados salvos precisam ser recuperados. Abra Meus dados e importe seu backup.');return false;}
 const nextMeta={...backupMeta,savedAt:new Date().toISOString()};
 try{storageTransaction(userStorageEntries(personal,{modules:done,leads2b:crmDone},guideTheme,nextMeta));backupMeta=nextMeta;personalSaved=true;storageOK=true;personalError='';}
 catch(e){personalSaved=false;storageOK=false;personalError=e.message;toast('Não foi possível salvar neste navegador. Exporte seus dados antes de fechar.');}
 updatePersonalStatus();refreshUserDataStatus();return personalSaved;
}
function refreshUserDataStatus(){if($('#dados.active'))renderUserData();}
function exportUserData(){
 if(personalLocked){toast('Recupere os dados salvos pela importação antes de exportar um novo backup.');return;}
 const now=new Date(),payload={format:backupFormat,schema:1,appVersion:guideVersion,exportedAt:now.toISOString(),personal:validatePersonal(personal),training:{modules:[...done],leads2b:[...crmDone]},preferences:{theme:guideTheme}};
 const date=deskToday(),time=now.toTimeString().slice(0,8).replaceAll(':','-'),name=(personal.profile.name||'televendas').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'_').slice(0,40)||'televendas';
 const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='Backup_PA_'+name+'_'+date+'_'+time+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
 backupMeta={...backupMeta,exportedAt:now.toISOString()};try{localStorage.setItem(backupMetaKey,JSON.stringify(backupMeta));}catch{}
 refreshUserDataStatus();toast('Backup preparado. Guarde o arquivo baixado para importar na nova versão.');
}
function parseUserBackup(raw){
 if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('Selecione um arquivo de backup da Central de Televendas.');
 if(raw.format==='pa-televendas-personal')return{personal:validatePersonal(raw),training:null,preferences:null,legacy:true,exportedAt:typeof raw.exportedAt==='string'?raw.exportedAt:'',appVersion:'7 ou 8',skipped:0};
 if(raw.format!==backupFormat)throw Error('Este arquivo não é um backup da Central de Televendas.');
 if(raw.schema!==1)throw Error('O formato deste backup precisa de uma edição mais recente da central.');
 const p=validatePersonal(raw.personal);
 if(!raw.training)throw Error('O backup está incompleto. Exporte uma nova cópia na versão de origem.');
 const ids=(v)=>{if(!Array.isArray(v)||v.length>1000||!v.every(x=>typeof x==='string'&&x.length>0&&x.length<=100))throw Error('As marcações de treinamento no arquivo são inválidas.');return[...new Set(v)]};
 const modules=ids(raw.training.modules),leads2b=ids(raw.training.leads2b),training={modules:modules.filter(id=>data.modules.some(m=>m.id===id)),leads2b:leads2b.filter(id=>data.crm.some(m=>m.id===id))};
 return{personal:p,training,preferences:{theme:guideTheme},legacy:false,exportedAt:typeof raw.exportedAt==='string'?raw.exportedAt:'',appVersion:typeof raw.appVersion==='string'?raw.appVersion.slice(0,30):'',skipped:modules.length+leads2b.length-training.modules.length-training.leads2b.length};
}
async function previewUserBackup(file){
 if(!file)return;pendingUserBackup=null;backupTrigger=document.activeElement;
 try{
  if(file.size>50000000)throw Error('Escolha um backup com até 50 MB.');
  let raw;try{raw=JSON.parse(await file.text())}catch{throw Error('Não foi possível ler o arquivo. Selecione o arquivo .json exportado pela central.');}
  const parsed=parseUserBackup(raw),c=userDataCounts(parsed.personal,parsed.training||{modules:[],leads2b:[]}),date=backupStamp(parsed.exportedAt);
  pendingUserBackup=parsed;
  $('#backup-preview').innerHTML=`<p class="backup-file-name">${esc(file.name)}</p><div class="backup-person"><span>Dados de</span><strong>${esc(parsed.personal.profile.name||'Pessoa sem nome definido')}</strong>${date?'<small>Exportado em '+esc(date)+'</small>':''}${parsed.appVersion?'<small>Versão de origem: '+esc(parsed.appVersion)+'</small>':''}</div><div class="backup-preview-counts"><div><strong>${c.months}</strong><span>meses</span></div><div><strong>${c.sales}</strong><span>vendas</span></div><div><strong>${c.tasks}</strong><span>tarefas</span></div><div><strong>${c.events}</strong><span>compromissos</span></div><div><strong>${parsed.legacy?'—':c.lessons}</strong><span>aulas marcadas</span></div></div><p class="backup-replace-note">${parsed.legacy?'Este é um backup antigo de Meu mês. Ele substitui suas metas, vendas, tarefas e calendário. As marcações de estudo atuais serão mantidas.':'A importação substitui seus registros de todos os meses e as marcações de estudo pelos dados deste arquivo.'}</p>${parsed.skipped?'<p class="backup-replace-note">'+parsed.skipped+' marcação(ões) de aulas ausentes nesta edição continuam disponíveis no arquivo de backup original.</p>':''}<p class="backup-before-import">Quer guardar os registros atuais? <button type="button" data-backup-action="export">Exporte uma cópia antes de importar.</button></p><p id="backup-import-error" class="backup-error" role="alert" hidden></p><div class="desk-form-actions"><button class="btn" type="button" data-backup-close>Cancelar</button><button class="btn primary" type="button" data-backup-action="confirm-import">Importar estes dados</button></div>`;
  $('#backup-dialog').showModal();
 }catch(e){toast(e.message);const msg=$('#backup-page-message');if(msg){msg.textContent=e.message;msg.hidden=false;}}
 finally{$('#desk-import-file').value='';}
}
function confirmUserImport(){
 const incoming=pendingUserBackup;if(!incoming)return;
 const training=incoming.training||{modules:[...done],leads2b:[...crmDone]};
 const nextMeta={...backupMeta,savedAt:new Date().toISOString(),importedAt:new Date().toISOString(),exportedAt:incoming.exportedAt&&Number.isFinite(Date.parse(incoming.exportedAt))?incoming.exportedAt:''};
 try{storageTransaction(userStorageEntries(incoming.personal,training,guideTheme,nextMeta));}
 catch(e){const message=$('#backup-import-error');message.textContent=e.message+' Você pode tentar novamente ou abrir a central em outro navegador e importar o mesmo arquivo.';message.hidden=false;return;}
 personal=incoming.personal;done=training.modules;crmDone=training.leads2b;backupMeta=nextMeta;personalLocked=false;personalSaved=true;storageOK=true;personalError='';pendingUserBackup=null;
 applyGuideTheme();updateProgress();$('#backup-dialog').close();route(false);updatePersonalStatus();toast('Dados importados e salvos. Você pode continuar de onde parou.');
}
function renderUserData(){
 const c=userDataCounts(),healthy=personalSaved&&storageOK&&!personalLocked,last=backupStamp(backupMeta.savedAt),exported=backupStamp(backupMeta.exportedAt),imported=backupStamp(backupMeta.importedAt);
 $('#dados').innerHTML=`<div class="pagehead"><div><div class="eyebrow">Sua rotina continua na próxima versão</div><h1>Meus dados</h1><p>Salve uma cópia e leve suas informações com você.</p></div></div><div class="backup-save-state ${healthy?'':'has-error'}" role="status"><span class="backup-state-dot" aria-hidden="true"></span><div><strong>${healthy?'Salvamento automático ativo':'Atenção ao salvamento'}</strong><p>${healthy?(last?'Última alteração salva em '+esc(last)+'.':'Suas alterações são salvas enquanto você usa a central.'):'As alterações podem estar apenas nesta sessão. Exporte seus dados antes de fechar.'}</p></div><button class="btn" type="button" data-backup-action="save">Salvar agora</button></div><p class="backup-local-note">O salvamento automático vale para este arquivo neste navegador. Para trocar de versão, arquivo ou computador, exporte e importe sua cópia.</p><div class="backup-actions"><section class="backup-action-card"><div class="backup-symbol">${di('download')}</div><h2>Exportar meus dados</h2><p>Baixe um único arquivo com suas informações e seu progresso. Ele leva todos os meses, mesmo os que não estão abertos agora.</p><button class="btn primary" type="button" data-backup-action="export">${di('download')} Exportar meus dados</button><small>${exported?'Última cópia exportada: '+esc(exported):'Crie uma cópia antes de abrir uma nova versão.'}</small></section><section class="backup-action-card"><div class="backup-symbol import-symbol">${di('download')}</div><h2>Importar meus dados</h2><p>Abra o arquivo .json que você exportou. Confira o nome e os registros antes de confirmar a importação.</p><button class="btn" type="button" data-backup-action="import">Selecionar arquivo de backup</button><small>${imported?'Última importação: '+esc(imported):'Também aceita backups antigos da área Meu mês.'}</small></section></div><p id="backup-page-message" class="backup-error" role="alert" hidden></p><section class="backup-included"><div class="backup-card-heading"><h2>O que vai na sua cópia</h2><span>${esc(personal.profile.name||'Seu perfil')}</span></div><div class="backup-counts"><div><strong>${c.months}</strong><span>meses com metas e rotina</span></div><div><strong>${c.sales}</strong><span>vendas registradas</span></div><div><strong>${c.tasks}</strong><span>tarefas e conclusões</span></div><div><strong>${c.events}</strong><span>compromissos no calendário</span></div><div><strong>${c.lessons}</strong><span>módulos e aulas estudados</span></div></div><p>Inclui também seu nome, dias de trabalho e folgas.</p></section><section class="backup-steps"><div class="eyebrow">Recebeu uma nova versão?</div><h2>Troque o arquivo sem começar do zero.</h2><ol><li><span>1</span><div><strong>Exporte na versão antiga</strong><p>Abra Meus dados e clique em Exportar meus dados. Guarde o arquivo .json baixado.</p></div></li><li><span>2</span><div><strong>Abra a nova versão</strong><p>Baixe e abra o novo HTML. Entre em Meus dados no menu.</p></div></li><li><span>3</span><div><strong>Importe e continue</strong><p>Selecione seu backup, confira as informações e clique em Importar estes dados.</p></div></li></ol><p class="backup-tip">Guarde a versão antiga e o backup até conferir seus registros na nova.</p></section>`;
}
document.addEventListener('click',e=>{
 const close=e.target.closest('[data-backup-close]');if(close){$('#backup-dialog').close();return;}
 const button=e.target.closest('[data-backup-action]');if(!button)return;
 const action=button.dataset.backupAction;
 if(action==='export')exportUserData();
 if(action==='import'){$('#backup-page-message')?.setAttribute('hidden','');$('#desk-import-file').click();}
 if(action==='save'&&persistUserData())toast('Seus dados foram salvos neste navegador.');
 if(action==='confirm-import')confirmUserImport();
});
$('#backup-dialog').addEventListener('close',()=>{pendingUserBackup=null;if(backupTrigger?.isConnected)backupTrigger.focus({preventScroll:true});else $('#main').focus({preventScroll:true});});



